// Convierte los fragmentos recuperados (ya filtrados por Minimum Score) en un bloque de contexto citable.
const params = $('Parámetros de recuperación (Top-K y Min Score)').first().json;
const items = $input.all().filter(i => i.json && typeof i.json.score === 'number');
if (items.length === 0) {
  return [{ json: {
    resultado: 'SIN_RESULTADOS',
    n_fragmentos: 0,
    top_k: params.top_k, min_score: params.min_score,
    contexto: 'SIN_RESULTADOS: ningún fragmento del Manual de Soporte y Ventas de Jumade superó la similitud mínima (' + params.min_score + ') para esta consulta. El dato NO está en la base de conocimiento: respondé "No sé" / "no tengo ese dato confirmado" y ofrecé derivar la consulta al equipo humano. No inventes.'
  } }];
}
const bloques = items.map((it, idx) => {
  const d = it.json.document || {}; const m = d.metadata || {};
  const texto = (d.pageContent || '').trim();
  return 'FRAGMENTO ' + (idx + 1) + ' | Fuente: ' + (m.documento || 'Manual de Jumade') + ' v' + (m.version || '') + ' › sección "' + (m.titulo || m.seccion || 's/d') + '" | similitud: ' + it.json.score.toFixed(3) + '\n' + texto;
});
return [{ json: {
  resultado: 'OK',
  n_fragmentos: items.length,
  top_k: params.top_k, min_score: params.min_score,
  fragmentos: items.map(it => ({ titulo: (it.json.document?.metadata?.titulo) || '', score: Number(it.json.score.toFixed(3)) })),
  contexto: bloques.join('\n\n---\n\n')
} }];
